export function aggregateScores(results){const totals=new Map();let frames=0;for(const frame of results||[]){const categories=frame?.classifications?.[0]?.categories;if(!categories?.length)continue;frames++;for(const c of categories){if(typeof c.categoryName!=='string'||!Number.isFinite(c.score))continue;totals.set(c.categoryName,(totals.get(c.categoryName)||0)+c.score);}}return frames?[...totals].map(([label,total])=>({label,score:total/frames})).sort((a,b)=>b.score-a.score):[];}
export function pickMission(scores){const good=scores.filter(s=>s.score>=.2).slice(0,5);if(good.some(s=>/Bird|Chirp|Tweet|Insect|Cricket/i.test(s.label)))return{title:'Listen beyond the birds.',text:'On your next ten-minute walk, find a safe place to pause. Listen for the quietest sound underneath the birds: leaves, insects, or your own footsteps.'};if(good.some(s=>/Water|Rain|Stream|Waves|Wind|Rustl/i.test(s.label)))return{title:'Follow a changing texture.',text:'Take a ten-minute walk and notice where the sound changes. From a safe path, compare one exposed listening spot with one sheltered spot. Keep a short note about the difference.'};if(good.some(s=>/Vehicle|Traffic|Engine|Car|Truck|Bus/i.test(s.label)))return{title:'Find a quieter listening stop.',text:'On a ten-minute walk along a familiar safe path, compare the street with a nearby quiet corner. Pause before recording and listen for a sound the traffic had hidden.'};return{title:'Find three layers of sound.',text:'Take a ten-minute walk somewhere familiar. Pause safely and listen for one near sound, one far sound, and one sound you almost missed.'};}
function csvCell(value){let s=String(value??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function csvForNotes(notes){return ['date,model_suggestion,field_note,source,top_model_score',...notes.map(n=>[n.date,n.title,n.note,n.source,n.scores?.[0]?.score??''].map(csvCell).join(','))].join('\r\n')+'\r\n';}
